/** Official mark URLs (Vite asset imports resolve to strings). */
export const ASSET_ICONS: Record<string, string> = {
  antigravity: assetAntigravity,
  "claude-code": assetClaudeCode,
  duckdb: assetDuckdb,
  "gemini-cli": assetGeminiCli,
  "github-copilot": assetGithubCopilot,
  gitlab: assetGitlab,
  "kimi-cli": assetKimiCli,
  mongodb: assetMongodb,
  mysql: assetMysql,
  opencode: assetOpencode,
  postgres: assetPostgres,
  "qwen-code": assetQwenCode,
  redis: assetRedis,
  sentry: assetSentry,
  sqlite: assetSqlite,
  terraform: assetTerraform,
};

export function isNamedMarkAsset(asset: string): boolean {
  return NAMED_MARK_ASSETS.has(asset);
}
